  function contacts(){return intro('P13','Будем на связи','Выберите тему обращения и удобный способ связи.')+section(1,'Способы связи',`<div class="grid three">${[['Общие вопросы','Общий контакт уточняется.'],['Партнёрство','Контакт по совместным программам уточняется.'],['Пресса','Контакт для редакций и интервью уточняется.']].map(([t,p])=>`<article class="card"><h3>${t}</h3><p>${p}</p><button class="text-link" data-contact-subject="${t==='Пресса'?'Для прессы':t==='Партнёрство'?t:'Общий вопрос'}">Написать по этой теме →</button></article>`).join('')}</div>`)+section(2,'Форма обращения',`<div class="grid two"><div><h2>Ваш вопрос</h2><p class="lead">Тема помогает направить обращение нужному человеку.</p>${note('Точный состав полей и адресаты уточняются.')}</div>${form('contact')}</div>`,{id:'contact-form'})+section(3,'Адрес и реквизиты',heading('Реквизиты и местонахождение')+placeholder('Полное наименование · юридический статус · адрес · реквизиты. Подтверждённые значения уточняются.'))+section(4,'Контакт для прессы',heading('Для редакций и журналистов')+`<p class="muted">Ответственный и прямой контакт уточняются. Здесь будут материалы для прессы и условия запроса комментария.</p><div class="actions"><button class="button secondary" data-contact-subject="Для прессы">Запрос для прессы →</button>${unknown('Материалы для прессы','Файлы пресс-кита и отдельный адрес служебной страницы уточняются.')}</div>`,{id:'press'})+section(5,'Социальные каналы',heading('Следить за деятельностью')+`<div class="actions">${out(D.sources.telegram,'Telegram','button secondary')}${out(D.sources.youtube,'YouTube','button secondary')}</div>${note('Ссылки взяты с действующего avanta.ru; перечень официальных каналов нужно подтвердить.')}`);}
  function components(){return `<div class="intro"><div class="wrap"><div class="eyebrow">Общие компоненты</div><h1>Поведение и состояния</h1><p class="lead">Служебный лист прототипа. Формы имитируют отправку, поля не сохраняются.</p></div></div>`+section(1,'Кнопки и навигация',`<div class="actions">${route('P12','Основное действие')}${route('P11','Второстепенное','secondary')}${link('P13','Контекстный переход')}${unknown('Неизвестный адрес')}</div>${note('Tab — переход по элементам; Enter и Space — действие; Escape — закрытие меню и диалога. Видимый фокус сохраняется.')}`)+section(2,'Карточки и раскрытия',`<div class="grid three"><article class="card"><h3>Эксперт</h3><p>Краткая и раскрытая карточка.</p>${modal('person',0,'Раскрыть эксперта')}</article>${bookCard(0)}<article class="card"><h3>Событие</h3><p>Отчёт, фотографии и видео.</p>${modal('event','e1','Раскрыть событие')}</article></div>`)+section(3,'Назначения форм',`<p class="demo-note">Переключатель состояний над макетом применяется ко всем формам на этом листе.</p><div class="grid two">${['join','education','partner','acceleration','contact','newsletter','conference'].map(k=>form(k)).join('')}</div>`);}
