    if(type==='event'){const ev=eventData.find(x=>x.id===id)||eventData[1];name=ev.title;body=tag(ev.role,'filled')+'<p class="meta-line">Дата · участники от ассоциации — уточняются</p><h3>Отчёт</h3>'+placeholder('Согласованное описание события, темы и результаты.')+'<h3>Фотографии</h3>'+ph('Фотографии события / подписи','wide')+'<h3>Видео и материалы</h3>'+ph('Запись выступления','wide')+`<div class="actions">${unknown('Открыть запись','Ссылка на запись этого события уточняется.')}${route('P10','Конференция','secondary')}</div>`;}
    if(type==='speaker'){const s=D.speakers[Number(id)]||D.speakers[0];name=e(s[0]);body=ph('Фото спикера','wide')+`<h3>${e(s[1])}</h3><p>Участник программы конференции «Лидерство в турбулентности» по действующему лендингу.</p>${placeholder('Место для согласованной расширенной биографии и темы выступления.')}${out(D.sources.conference,'Проверить сведения на лендинге','source')}<div class="actions"><a class="button" href="#${state==='after'?'block-4':'registration'}" data-modal-anchor="${state==='after'?'block-4':'registration'}">${state==='after'?'Вернуться к участникам':'К участию и регистрации'} →</a></div>`;}
